package com.northstarbank.core;
import jakarta.validation.Valid;import jakarta.validation.constraints.*;import java.math.BigDecimal;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.time.LocalDate;import java.util.*;import org.springframework.http.*;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/core") class CoreController{
 private final CustomerRepo customers;private final AccountRepo accounts;private final TransactionRepo transactions;private final CardRepo cards;private final PostingRepo postings;private final ScopeToken tokens;
 CoreController(CustomerRepo c,AccountRepo a,TransactionRepo t,CardRepo cards,PostingRepo p,ScopeToken s){customers=c;accounts=a;transactions=t;this.cards=cards;postings=p;tokens=s;}
 @GetMapping("/customers/search") List<CustomerView> search(@RequestHeader("Authorization")String auth,@RequestParam @Size(max=80)String q){var cl=tokens.verify(auth);var found=new LinkedHashMap<String,CoreCustomer>();customers.findByFullNameContainingIgnoreCaseOrIdContainingIgnoreCaseOrPhoneContaining(q,q,q).forEach(c->found.put(c.id,c));accounts.findById(q).flatMap(a->customers.findById(a.customerId)).ifPresent(c->found.put(c.id,c));return found.values().stream().filter(c->allowed(cl,c.branch)&&!c.vulnerable||allowedVulnerable(cl,c)).limit(30).map(CustomerView::of).toList();}
 @GetMapping("/customers/{id}") Customer360 customer(@RequestHeader("Authorization")String auth,@PathVariable @Pattern(regexp="C\\d{4}")String id){var c=customers.findById(id).orElseThrow(NotFound::new);var cl=tokens.verify(auth);tokens.require(cl,c.branch);if(c.vulnerable&&!allowedVulnerable(cl,c))throw new ScopeToken.OutOfScope();return new Customer360(CustomerView.of(c),accounts.findByCustomerId(id),cards.findByCustomerId(id));}
 @PatchMapping("/customers/{id}/contact") @Transactional CustomerView contact(@RequestHeader("Authorization")String auth,@PathVariable String id,@Valid @RequestBody ContactCommand cmd){var c=customers.findById(id).orElseThrow(NotFound::new);tokens.require(tokens.verify(auth),c.branch);c.phone=cmd.phone();c.email=cmd.email();return CustomerView.of(c);}
 @GetMapping("/accounts/{account}/transactions") List<CoreTransaction> transactions(@RequestHeader("Authorization")String auth,@PathVariable String account,@RequestParam LocalDate from,@RequestParam LocalDate to){var a=accounts.findById(account).orElseThrow(NotFound::new);var c=customers.findById(a.customerId).orElseThrow(NotFound::new);tokens.require(tokens.verify(auth),c.branch);return transactions.findTop100ByAccountNumberAndBookingDateBetweenOrderByBookingDateDesc(account,from,to);}
 @PostMapping("/cards/{id}/transition") @Transactional CoreCard card(@RequestHeader("Authorization")String auth,@PathVariable String id,@Valid @RequestBody CardCommand cmd){CoreCard card=cards.findById(id).orElseThrow(NotFound::new);CoreCustomer c=customers.findById(card.customerId).orElseThrow(NotFound::new);ScopeToken.Claims cl=tokens.verify(auth);tokens.require(cl,c.branch);if(Set.of("CSR","SECURITY_ADMIN").contains(cl.role()))throw new ScopeToken.OutOfScope();String from=card.status;boolean ok=switch(cmd.action()){case "temporary_block"->from.equals("active");case "permanent_block"->Set.of("active","temporarily_blocked").contains(from);case "unblock"->from.equals("temporarily_blocked");case "reissue"->Set.of("active","temporarily_blocked").contains(from);default->false;};if(!ok)throw new InvalidTransition();if(cmd.action().equals("reissue")){card.status="replaced";CoreCard replacement=new CoreCard(UUID.randomUUID().toString(),card.accountNumber,card.customerId,"•••• •••• •••• "+String.format("%04d",new Random().nextInt(10000)),"active");replacement.replacementOf=card.id;cards.save(replacement);}else card.status=switch(cmd.action()){case "temporary_block"->"temporarily_blocked";case "permanent_block"->"permanently_blocked";default->"active";};card.blockReason=cmd.reason();return card;}
 @PostMapping("/postings") @Transactional CorePosting post(@RequestHeader("Authorization")String auth,@Valid @RequestBody PostingCommand cmd){CoreCustomer c=customers.findById(cmd.customerId()).orElseThrow(NotFound::new);tokens.require(tokens.verify(auth),c.branch);return postings.findByRequestIdAndOperation(cmd.requestId(),cmd.operation()).orElseGet(()->postings.save(new CorePosting(cmd.requestId(),cmd.operation(),cmd.customerId(),cmd.amount())));}
 @GetMapping("/branches") ResponseEntity<List<Map<String,String>>> branches(@RequestHeader("Authorization")String auth)throws Exception{tokens.verify(auth);var body=java.util.stream.IntStream.rangeClosed(1,9).mapToObj(i->Map.of("id","B0"+i,"name","Branch "+i)).toList();MessageDigest md=MessageDigest.getInstance("MD5"); // Non-cryptographic: MD5 is used only as a reference-data HTTP ETag.
  String etag=HexFormat.of().formatHex(md.digest(body.toString().getBytes(StandardCharsets.UTF_8)));return ResponseEntity.ok().eTag(etag).body(body);}
 private boolean allowed(ScopeToken.Claims c,String b){try{tokens.require(c,b);return true;}catch(RuntimeException e){return false;}}
 private boolean allowedVulnerable(ScopeToken.Claims c,CoreCustomer x){return allowed(c,x.branch)&&Set.of("BRANCH_SUPERVISOR","REGIONAL_MANAGER","HEAD_OFFICE_OPS").contains(c.role());}
 record CustomerView(String id,String fullName,String phone,String email,String branch,boolean vulnerable){static CustomerView of(CoreCustomer c){return new CustomerView(c.id,c.fullName,c.phone,c.email,c.branch,c.vulnerable);}}
 record Customer360(CustomerView customer,List<CoreAccount> accounts,List<CoreCard> cards){}
 record CardCommand(@NotBlank String action,@NotBlank @Size(max=160)String reason){}
 record ContactCommand(@NotBlank @Size(max=40) String phone,@Email @Size(max=160) String email){}
 record PostingCommand(@NotBlank String requestId,@Pattern(regexp="FEE_REVERSAL|LIMIT_OVERRIDE")String operation,@Pattern(regexp="C\\d{4}")String customerId,@DecimalMin("0.01")BigDecimal amount){}
 @ExceptionHandler({NotFound.class,ScopeToken.OutOfScope.class})ResponseEntity<Void> hidden(){return ResponseEntity.notFound().build();}
 @ExceptionHandler(ScopeToken.InvalidScopeToken.class)ResponseEntity<Void> unauthorized(){return ResponseEntity.status(401).build();}
 @ResponseStatus(HttpStatus.CONFLICT) static class InvalidTransition extends RuntimeException{} static class NotFound extends RuntimeException{}
}
